import dns from "node:dns/promises";
import { BlockList, isIPv4, isIPv6 } from "node:net";
import { rootLogger } from "../shared/logger";

const logger = rootLogger.child("deploy-hook");

const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 250;
const MAX_REDIRECTS = 3;

export interface DeployHookResult {
  readonly ok: boolean;
  readonly attempts: number;
}

/**
 * Address ranges no deploy hook should ever be allowed to reach: loopback,
 * the RFC1918 and CGNAT private ranges, link-local (which is also where a
 * cloud's instance-metadata endpoint lives — 169.254.169.254 on AWS/GCP/
 * Azure alike), and the multicast/reserved space above it. `deployHookUrl`
 * is a plain text field a customer fills in, so this list is what stands
 * between "publish" and an attacker using this API as a proxy into whatever
 * network it happens to run on.
 */
const FORBIDDEN_ADDRESSES = new BlockList();
for (const [address, prefix] of [
  ["0.0.0.0", 8], // "this network"
  ["10.0.0.0", 8], // RFC1918
  ["100.64.0.0", 10], // carrier-grade NAT
  ["127.0.0.0", 8], // loopback
  ["169.254.0.0", 16], // link-local, incl. cloud metadata endpoints
  ["172.16.0.0", 12], // RFC1918
  ["192.168.0.0", 16], // RFC1918
  ["224.0.0.0", 4], // multicast
  ["240.0.0.0", 4], // reserved
] as const) {
  FORBIDDEN_ADDRESSES.addSubnet(address, prefix, "ipv4");
}
for (const [address, prefix] of [
  ["::1", 128], // loopback
  ["::", 128], // unspecified
  ["64:ff9b::", 96], // NAT64 well-known prefix — resolves through to an IPv4 target
  ["fc00::", 7], // unique local (includes AWS's fd00:ec2::254 metadata address)
  ["fe80::", 10], // link-local
  ["ff00::", 8], // multicast
] as const) {
  FORBIDDEN_ADDRESSES.addSubnet(address, prefix, "ipv6");
}

export class UnsafeDeployHookUrlError extends Error {}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function stripBrackets(hostname: string): string {
  return hostname.startsWith("[") && hostname.endsWith("]")
    ? hostname.slice(1, -1)
    : hostname;
}

function isForbiddenAddress(address: string): boolean {
  if (isIPv4(address)) return FORBIDDEN_ADDRESSES.check(address, "ipv4");
  if (isIPv6(address)) return FORBIDDEN_ADDRESSES.check(address, "ipv6");
  return true; // an address net.isIP doesn't recognize is not one we trust
}

/**
 * Parses and resolves a candidate deploy hook URL and throws
 * `UnsafeDeployHookUrlError` unless every address it resolves to is
 * ordinary public internet. Called before the initial request and again
 * before following any redirect, since a URL that resolves safely once can
 * still point a redirect at something that doesn't.
 */
export async function assertSafeDeployHookUrl(rawUrl: string): Promise<URL> {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    throw new UnsafeDeployHookUrlError(`"${rawUrl}" is not a valid URL.`);
  }

  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new UnsafeDeployHookUrlError(`"${url.protocol}" is not an allowed deploy hook scheme.`);
  }

  if (url.username || url.password) {
    throw new UnsafeDeployHookUrlError("A deploy hook URL may not carry credentials.");
  }

  const hostname = stripBrackets(url.hostname);
  if (hostname === "localhost") {
    throw new UnsafeDeployHookUrlError('"localhost" is not an allowed deploy hook host.');
  }

  let addresses: string[];
  try {
    addresses = (await dns.lookup(hostname, { all: true })).map((result) => result.address);
  } catch {
    throw new UnsafeDeployHookUrlError(`"${hostname}" could not be resolved.`);
  }

  if (addresses.length === 0 || addresses.some(isForbiddenAddress)) {
    throw new UnsafeDeployHookUrlError(`"${hostname}" resolves to an address this app won't call.`);
  }

  return url;
}

function isRedirect(response: Response): boolean {
  return response.status >= 300 && response.status < 400 && response.headers.has("location");
}

/**
 * Follows redirects itself instead of letting `fetch` do it, re-checking
 * every hop with `assertSafeDeployHookUrl` first. A hook that resolves
 * safely can still answer with a 302 to an internal address, and `fetch`'s
 * own redirect handling would follow that without a second look.
 */
async function postToSafeUrl(url: URL): Promise<Response> {
  let current = url;
  for (let hop = 0; ; hop += 1) {
    const response = await fetch(current, { method: "POST", redirect: "manual" });
    if (!isRedirect(response)) return response;
    if (hop >= MAX_REDIRECTS) {
      throw new UnsafeDeployHookUrlError(`Deploy hook redirected more than ${MAX_REDIRECTS} times.`);
    }
    const location = response.headers.get("location") ?? "";
    current = await assertSafeDeployHookUrl(new URL(location, current).toString());
  }
}

/**
 * Calls a site's deploy hook after a publish. Most static-hosting deploy
 * hooks are a bare POST with no body, and most are flaky enough on a cold
 * start to be worth one retry — this gives it two.
 *
 * A failed hook does not fail the publish: the post and its revision are
 * already committed by the time this runs (see routes in app.ts), so the
 * worst case is a site that doesn't rebuild on its own. The caller surfaces
 * `ok: false` to the editor rather than losing the failure silently.
 *
 * `url` is a value a customer typed into a text field, not one this app
 * chose — see `assertSafeDeployHookUrl` for what that means for where this
 * function is willing to send a request.
 */
export async function triggerDeployHook(siteSlug: string, url: string): Promise<DeployHookResult> {
  let safeUrl: URL;
  try {
    safeUrl = await assertSafeDeployHookUrl(url);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    logger.warn({ siteSlug, reason }, "Refused to call an unsafe deploy hook URL.");
    return { ok: false, attempts: 0 };
  }

  let lastError: unknown;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    try {
      logger.debug({ siteSlug, attempt }, "Started calling the deploy hook.");
      const response = await postToSafeUrl(safeUrl);
      if (!response.ok) {
        throw new Error(`Deploy hook responded with status ${response.status}.`);
      }
      logger.info({ siteSlug, attempt }, "Completed calling the deploy hook.");
      return { ok: true, attempts: attempt };
    } catch (error) {
      lastError = error;
      const reason = error instanceof Error ? error.message : String(error);
      logger.warn({ siteSlug, attempt, reason }, "Deploy hook call failed; retrying.");
      if (attempt < MAX_ATTEMPTS) await sleep(RETRY_DELAY_MS * attempt);
    }
  }

  const reason = lastError instanceof Error ? lastError.message : String(lastError);
  logger.error(
    { siteSlug, attempts: MAX_ATTEMPTS, reason },
    "Deploy hook failed after every retry.",
  );
  return { ok: false, attempts: MAX_ATTEMPTS };
}

