import dns from "node:dns/promises";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { assertSafeDeployHookUrl, triggerDeployHook, UnsafeDeployHookUrlError } from "./deploy-hook";

vi.mock("node:dns/promises", () => ({
  default: { lookup: vi.fn() },
}));

const lookupMock = vi.mocked(dns.lookup);

describe("assertSafeDeployHookUrl", () => {
  beforeEach(() => {
    lookupMock.mockResolvedValue([{ address: "203.0.113.10", family: 4 }]);
  });

  it("accepts a URL that resolves to an ordinary public address", async () => {
    await expect(assertSafeDeployHookUrl("https://hooks.example.invalid/deploy/acme")).resolves.toBeInstanceOf(
      URL,
    );
  });

  it("rejects a value that isn't a URL at all", async () => {
    await expect(assertSafeDeployHookUrl("not a url")).rejects.toThrow(UnsafeDeployHookUrlError);
  });

  it("rejects a non-http(s) scheme", async () => {
    await expect(assertSafeDeployHookUrl("file:///etc/passwd")).rejects.toThrow(UnsafeDeployHookUrlError);
  });

  it("rejects a URL carrying credentials", async () => {
    await expect(
      assertSafeDeployHookUrl("https://user:pass@hooks.example.invalid/deploy/acme"),
    ).rejects.toThrow(UnsafeDeployHookUrlError);
  });

  it('rejects "localhost"', async () => {
    await expect(assertSafeDeployHookUrl("http://localhost:5432/")).rejects.toThrow(UnsafeDeployHookUrlError);
  });

  it("rejects a hostname that resolves to a loopback address", async () => {
    lookupMock.mockResolvedValue([{ address: "127.0.0.1", family: 4 }]);
    await expect(assertSafeDeployHookUrl("https://sneaky.example.invalid/")).rejects.toThrow(
      UnsafeDeployHookUrlError,
    );
  });

  it("rejects a hostname that resolves to an RFC1918 address", async () => {
    lookupMock.mockResolvedValue([{ address: "10.0.5.5", family: 4 }]);
    await expect(assertSafeDeployHookUrl("https://sneaky.example.invalid/")).rejects.toThrow(
      UnsafeDeployHookUrlError,
    );
  });

  it("rejects a hostname that resolves to the cloud metadata address", async () => {
    lookupMock.mockResolvedValue([{ address: "169.254.169.254", family: 4 }]);
    await expect(assertSafeDeployHookUrl("https://sneaky.example.invalid/")).rejects.toThrow(
      UnsafeDeployHookUrlError,
    );
  });

  it("rejects a hostname that resolves to an IPv6 unique-local address", async () => {
    lookupMock.mockResolvedValue([{ address: "fd00::1", family: 6 }]);
    await expect(assertSafeDeployHookUrl("https://sneaky.example.invalid/")).rejects.toThrow(
      UnsafeDeployHookUrlError,
    );
  });

  it("rejects a hostname that resolves to more than one address if any of them is private", async () => {
    lookupMock.mockResolvedValue([
      { address: "203.0.113.10", family: 4 },
      { address: "10.0.0.5", family: 4 },
    ]);
    await expect(assertSafeDeployHookUrl("https://sneaky.example.invalid/")).rejects.toThrow(
      UnsafeDeployHookUrlError,
    );
  });

  it("rejects a hostname that fails to resolve", async () => {
    lookupMock.mockRejectedValue(new Error("ENOTFOUND"));
    await expect(assertSafeDeployHookUrl("https://does-not-resolve.example.invalid/")).rejects.toThrow(
      UnsafeDeployHookUrlError,
    );
  });
});

describe("triggerDeployHook", () => {
  beforeEach(() => {
    vi.stubGlobal("fetch", vi.fn());
    lookupMock.mockResolvedValue([{ address: "203.0.113.10", family: 4 }]);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("succeeds on the first attempt", async () => {
    vi.mocked(fetch).mockResolvedValue(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 1 });
    expect(fetch).toHaveBeenCalledTimes(1);
  });

  it("retries once after a network failure and then succeeds", async () => {
    vi.mocked(fetch)
      .mockRejectedValueOnce(new Error("network down"))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 2 });
  });

  it("treats a non-2xx response as a failure worth retrying", async () => {
    vi.mocked(fetch)
      .mockResolvedValueOnce(new Response(null, { status: 503 }))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(true);
    expect(fetch).toHaveBeenCalledTimes(2);
  });

  it("gives up after exhausting every retry", async () => {
    vi.mocked(fetch).mockRejectedValue(new Error("network down"));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(false);
    expect(result.attempts).toBe(3);
    expect(fetch).toHaveBeenCalledTimes(3);
  });

  it("refuses to call a hook URL that resolves to a private address, without touching the network", async () => {
    lookupMock.mockResolvedValue([{ address: "10.1.2.3", family: 4 }]);

    const result = await triggerDeployHook("acme", "https://sneaky.example.invalid/");

    expect(result).toEqual({ ok: false, attempts: 0 });
    expect(fetch).not.toHaveBeenCalled();
  });

  it("follows a redirect to another safe address", async () => {
    vi.mocked(fetch)
      .mockResolvedValueOnce(
        new Response(null, { status: 302, headers: { location: "https://also-safe.example.invalid/deploy" } }),
      )
      .mockResolvedValueOnce(new Response(null, { status: 200 }));

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result).toEqual({ ok: true, attempts: 1 });
    expect(fetch).toHaveBeenCalledTimes(2);
  });

  it("refuses to follow a redirect into a private address", async () => {
    lookupMock.mockImplementation(async (hostname) => {
      if (hostname === "internal.example.invalid") return [{ address: "169.254.169.254", family: 4 }];
      return [{ address: "203.0.113.10", family: 4 }];
    });
    vi.mocked(fetch).mockResolvedValue(
      new Response(null, { status: 302, headers: { location: "http://internal.example.invalid/steal" } }),
    );

    const result = await triggerDeployHook("acme", "https://hooks.example.invalid/deploy/acme");

    expect(result.ok).toBe(false);
    expect(fetch).toHaveBeenCalledTimes(1);
  });
});

